#!/usr/bin/env python3
"""Authoring source for data/ship_layout.json (the Cinder Wake).

Run:  python3 tools/author_layout.py
The game reads only the generated JSON; this script exists because the layout
is easier to author and review as Python data (comments, helpers, loops).
Coordinates are metres on a 1 m grid; rects are [x0, z0, x1, z1) in cells.
"""
import json
import os

OUT = os.path.join(os.path.dirname(__file__), "..", "data", "ship_layout.json")

L = {
    "_comment": "GENERATED by tools/author_layout.py - edit that file, not this one.",
    "grid": {"min_x": 0, "min_z": -10, "w": 180, "h": 42},
    "player_start": {"pos": [4.6, 6.0], "rot": 90},
    "areas": {},
    "doors": [],
    "props": [],
    "signs": [],
    "objects": [],
    "npcs": {},
    "triggers": [],
}

def area(aid, name, rects, floor, wall, accent, light, sub="", **kw):
    a = {"name": name, "subtitle": sub, "rects": rects, "floor": floor, "wall": wall,
         "accent": accent, "light": light}
    a.update(kw)
    L["areas"][aid] = a

def door(did, cells, a, b, kind="door", name="Door", **kw):
    d = {"id": did, "cells": cells, "a": a, "b": b, "kind": kind, "name": name}
    d.update(kw)
    L["doors"].append(d)

def prop(t, p, s=(1, 1), h=1.0, c="#4a515c", **kw):
    d = {"t": t, "p": list(p), "s": list(s), "h": h, "c": c}
    d.update(kw)
    L["props"].append(d)

def sign(text, p, rot=0, c="#f2c26b", size=64):
    L["signs"].append({"text": text, "p": list(p), "rot": rot, "c": c, "size": size})

def obj(oid, typ, area_id, pos, **kw):
    d = {"id": oid, "type": typ, "area": area_id, "pos": list(pos)}
    d.update(kw)
    L["objects"].append(d)

def npc(nid, name, area_id, pos, rot=0, **kw):
    d = {"name": name, "area": area_id, "pos": list(pos), "rot": rot}
    d.update(kw)
    L["npcs"][nid] = d

def trigger(tid, rect, **kw):
    d = {"id": tid, "rect": list(rect)}
    d.update(kw)
    L["triggers"].append(d)

