# Content (objects, NPCs, triggers) lives in a separate module for readability.
import importlib.util
spec = importlib.util.spec_from_file_location("layout_content", os.path.join(os.path.dirname(__file__), "layout_content.py"))
mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)
mod.populate(L, obj, npc, trigger)

with open(OUT, "w") as f:
    json.dump(L, f, indent=1)
print("wrote", OUT, len(L["objects"]), "objects", len(L["npcs"]), "npcs", len(L["props"]), "props")
